/**
 * Server-side data loaders.
 *
 * Uses Vite's ?raw import so the YAML is inlined at build time, then parses and
 * validates it. Validation matters here: these two files are hand-edited and
 * regenerated by scripts/fetch-publications.mjs, and an unchecked `as` cast
 * would let a typo (a missing year, a misspelled type) reach the rendered page
 * as `undefined`. A bad edit now fails the build with the offending path.
 */
import yaml from 'js-yaml';
import { z } from 'astro/zod';
import siteYaml from '~/data/site.yaml?raw';
import pubsYaml from '~/data/publications.yaml?raw';

const SiteSchema = z.object({
  name: z.string(),
  shortName: z.string(),
  role: z.string(),
  affiliation: z.string(),
  tagline: z.string(),
  description: z.string(),
  email: z.email(),
  orcid: z.string().regex(/^\d{4}-\d{4}-\d{4}-\d{3}[\dX]$/, 'expected a 16-digit ORCID iD'),
  scholar: z.url(),
  linkedin: z.url(),
  github: z.url(),
  researchgate: z.url(),
  uea_profile: z.url(),
  office: z.object({
    room: z.string(),
    address: z.string(),
    postcode: z.string(),
  }),
  lastUpdated: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'expected YYYY-MM-DD'),
  phdStatus: z.enum(['open', 'closed', 'seasonal']),
  phdStatusLabel: z.string(),
  phdStatusNote: z.string(),
  defaultNewsType: z.string(),
});

const PublicationSchema = z.object({
  id: z.string(),
  authors: z.array(z.string()),
  year: z.number().int().min(1900).max(2100),
  title: z.string().min(1),
  venue: z.string().nullable(),
  /** Volume/issue/pages, kept separate from the venue so it is not italicised. */
  biblio: z.string().nullable().optional(),
  type: z.enum(['article', 'chapter', 'report', 'conference', 'preprint']),
  doi: z.string().nullable().optional(),
  url: z.string().nullable().optional(),
  pdf: z.string().nullable().optional(),
  award: z.string().nullable().optional(),
  role: z.enum(['first', 'middle', 'last']).nullable().optional(),
  notes: z.string().nullable().optional(),
});

export type SiteData = z.infer<typeof SiteSchema>;
export type Publication = z.infer<typeof PublicationSchema>;

function parse<T>(schema: z.ZodType<T>, raw: string, file: string): T {
  const result = schema.safeParse(yaml.load(raw));
  if (!result.success) {
    const detail = result.error.issues
      .map((i) => `  ${i.path.join('.') || '(root)'}: ${i.message}`)
      .join('\n');
    throw new Error(`Invalid data in ${file}:\n${detail}`);
  }
  return result.data;
}

export const site = parse(SiteSchema, siteYaml, 'src/data/site.yaml');
export const publications = parse(
  z.array(PublicationSchema),
  pubsYaml,
  'src/data/publications.yaml',
);
